स्मृतिभ्रंशाद्बुद्धिनाशो बुद्धिनाशात्प्रणश्यति ॥ ६३ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":909,\"bb\":815,\"url_path\":\"/en/library/bg/2/63/b815/\",\"body_value\":\"krodhād bhavati sammohaḥ
sammohāt smṛti-vibhramaḥ
smṛti-bhraṁśād buddhi-nāśo
buddhi-nāśāt praṇaśyati\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":910,\"bb\":816,\"url_path\":\"/en/library/bg/2/63/b816/\",\"shadow_value\":\"krodhāt – from anger; bhavati – takes place; sammohaḥ – perfect illusion; sammohāt – from illusion; smṛti – of memory; vibhramaḥ – bewilderment; smṛti-bhraṁśāt – after bewilderment of memory; buddhi-nāśaḥ – loss of intelligence; buddhi-nāśāt – and from loss of intelligence; praṇaśyati – one falls down.\",\"word_for_word_value\":[{\"word\":\"krodhāt\",\"translation\":\"from anger\"},{\"word\":\"bhavati\",\"translation\":\"takes place\"},{\"word\":\"sammohaḥ\",\"translation\":\"perfect illusion\"},{\"word\":\"sammohāt\",\"translation\":\"from illusion\"},{\"word\":\"smṛti\",\"translation\":\"of memory\"},{\"word\":\"vibhramaḥ\",\"translation\":\"bewilderment\"},{\"word\":\"smṛti-bhraṁśāt\",\"translation\":\"after bewilderment of memory\"},{\"word\":\"buddhi-nāśaḥ\",\"translation\":\"loss of intelligence\"},{\"word\":\"buddhi-nāśāt\",\"translation\":\"and from loss of intelligence\"},{\"word\":\"praṇaśyati\",\"translation\":\"one falls down\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":911,\"bb\":817,\"url_path\":\"/en/library/bg/2/63/b817/\",\"body_value\":\"From anger, complete delusion arises, and from delusion bewilderment of memory. When memory is bewildered, intelligence is lost, and when intelligence is lost one falls down again into the material pool.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":912,\"bb\":818,\"url_path\":\"/en/library/bg/2/63/b818/\",\"body_value\":\"Śrīla Rūpa Gosvāmī has given us this direction:\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":913,\"bb\":819,\"url_path\":\"/en/library/bg/2/63/b819/\",\"body_value\":\"prāpañcikatayā buddhyā
